function energySVG(e,f,y){const max=f*y*1.12,pt=(v,i)=>`${45+i*62},${200-v/max*165}`,eline=Array.from({length:y+1},(_,i)=>pt(e*i,i)).join(' '),fline=Array.from({length:y+1},(_,i)=>pt(f*i,i)).join(' ');return `<svg viewBox="0 0 400 235" role="img" aria-label="五年电车能源费用18000元，燃油车64000元，差额46000元"><line x1="45" y1="200" x2="360" y2="200" stroke="#e1e4e7"/>${[20000,40000,60000].map(v=>`<line x1="45" y1="${200-v/max*165}" x2="360" y2="${200-v/max*165}" stroke="#eef0f2"/><text x="0" y="${204-v/max*165}" fill="#92979d" font-size="10">${v/10000}万</text>`).join('')}<polyline points="${fline}" fill="none" stroke="#8294a7" stroke-width="2.5"/><polyline points="${eline}" fill="none" stroke="#397b61" stroke-width="2.5"/><text x="305" y="${190-f*y/max*165}" fill="#647d97" font-size="11">${money(f*y)}</text><text x="305" y="${190-e*y/max*165}" fill="#397b61" font-size="11">${money(e*y)}</text>${Array.from({length:y+1},(_,i)=>`<text x="${45+i*62}" y="220" text-anchor="middle" fill="#92979d" font-size="10">${i}年</text>`).join('')}</svg>`;}
if($('#report')){renderReport();return;}
